export const MODULE_CSS = "/* module: contact-form */\n/*\n * REQ-96 — every rule here belongs to an INVARIANT element: presentation fixed\n * by an obligation, not by taste (DOC-25 §10.3). There is deliberately nothing\n * about a field's surface, height, spacing or arrangement — all of that is the\n * `form` slot's L1 subtree, and the module has no way to express it.\n */\n\n/* The module's own chrome must contribute no layout to the L1 it wraps. */\n.contact-form,\n.contact-form__inner,\n.contact-form__form { margin: 0; padding: 0; border: 0; }\n\n/*\n * The programmatic label: present and associated for assistive technology,\n * removed from the visual flow so it neither paints nor displaces the L1\n * layout. Obligation, not styling — which is why a designer cannot vary it.\n */\n.contact-form__label {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n  border: 0;\n}\n\n/* Honeypot is removed from the visual + accessibility tree without display:none\n   (some bots skip display:none fields). */\n.contact-form__honeypot {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n}\n\n/* The Turnstile mount sits where the widget expects it and takes no space\n   until the widget occupies it. */\n.contact-form__turnstile { margin: 0; }\n\n/* The inline error surface — shown only by the client enhancement. */\n.contact-form__error { margin: 0; }\n\n/* module: carousel */\n/*\n * REQ-96 — every rule here is behavioural mechanics or an invariant state\n * signal. There is deliberately no `gap`, no `flex-basis`, and nothing about a\n * dot's size or colour: a slide's width is its own L1 subtree's sizing, and a\n * dot's look is the L1 control node naming it.\n */\n\n/* The track — a pure CSS scroll-snap row: genuinely swipeable/scrollable, no JS. */\n.carousel__track {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  overflow-x: auto;\n  scroll-snap-type: x mandatory;\n  scroll-behavior: smooth;\n  width: 100%;\n  scrollbar-width: none;\n}\n.carousel__track::-webkit-scrollbar { display: none; }\n\n/* A slide is a snap target sized by its own content — never by a view dial. */\n.carousel__slide {\n  scroll-snap-align: center;\n  flex: 0 0 auto;\n  min-width: 0;\n}\n\n/*\n * REQ-116 — the settled state, for the edit render only.\n *\n * The slides are all in the DOM already (a scroll track, not `display: none`),\n * so their copy is reachable — but with behaviour off they sit scrolled out of\n * view, which makes them awkward to click and impossible to see. Nothing in\n * the edit channel is interactive enough to reveal them, so the track wraps\n * and every slide is on screen simultaneously.\n *\n * The rule keys off the document-level `data-fc-edit` marker the page\n * assembler sets on `<body>`, so it is inert in every other channel. Any future\n * behavior module that hides content behind its behaviour declares its own\n * settled state the same way — the channel does not need to know what a\n * carousel is.\n */\n[data-fc-edit] .carousel__track {\n  flex-wrap: wrap;\n  overflow-x: visible;\n  scroll-snap-type: none;\n}\n\n/*\n * The one invariant state signal (DOC-25 §10.3): which slide is current must\n * be discernible, and a static L1 subtree has no state axis to say it with.\n * Opacity is the minimal, size- and colour-agnostic way to express it, so the\n * dot's actual look stays entirely L1's.\n */\n[data-carousel-dot] { opacity: 0.4; }\n[data-carousel-dot][data-carousel-current] { opacity: 1; }"

