export const MODULE_CLIENT_JS = "/* behavior: contact-form */\n/**\n * Vetted client behaviour for the `contact-form` behavior (REQ-85).\n *\n * The server-rendered form works with no JavaScript: a real `<form\n * method=\"post\" action=…>` submits by reloading against the endpoint. This\n * upgrades that baseline — when JS runs, the submit is intercepted and sent as a\n * JSON `fetch`, keeping the visitor on the page and swapping in the success\n * message inline.\n *\n * Authored as self-contained browser JavaScript (no imports) so the render\n * pipeline ships it verbatim in `capabilities.js`; unit-tested by importing this\n * module against a JSDOM + mocked `fetch`. **Isolation** (REQ-85): defensive\n * throughout, so a failure degrades to the no-JS post baseline.\n */\n\nconst ROOT_SELECTOR = '[data-contact-form-root]'\nconst ERROR_SELECTOR = '[data-contact-error]'\nconst SUCCESS_SELECTOR = '[data-contact-success]'\n\nfunction showError(form, message) {\n  const errorEl = form.querySelector(ERROR_SELECTOR)\n  if (errorEl) {\n    errorEl.textContent = message\n    errorEl.hidden = false\n  }\n}\n\n/**\n * BUG-28 — whether this submission can be enhanced at all.\n *\n * `assertSafeUrl` accepts `mailto:` and `tel:` actions, but `fetch()` cannot send\n * to either: it rejects, and the catch below reports \"could not reach the server\"\n * on a form that would have worked perfectly by native submit. Worse, the\n * `preventDefault()` had already cancelled that native submit — so the vetted\n * no-JS baseline this file documents as its degradation path was unreachable for\n * exactly the actions that needed it.\n *\n * The scheme already carries the answer, so no config field is added for it\n * (DOC-25 §2 — a dial for something the data determines is the wrong shape).\n * http(s), relative, and empty (post-to-self) enhance; anything else, including\n * anything unparseable, falls through to the browser.\n */\nfunction canEnhance(action) {\n  try {\n    const scheme = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(String(action).trim())\n    return !scheme || /^https?$/i.test(scheme[1])\n  } catch (_e) {\n    return false\n  }\n}\n\nasync function handleSubmit(form, event) {\n  // Decided BEFORE preventDefault, so a non-fetchable action keeps its native submit.\n  if (!canEnhance(form.getAttribute('action') || '')) return\n  event.preventDefault()\n\n  const errorEl = form.querySelector(ERROR_SELECTOR)\n  if (errorEl) {\n    errorEl.hidden = true\n    errorEl.textContent = ''\n  }\n\n  // Serialise the form's named controls to a flat JSON object — the honeypot\n  // field rides along so the server can reject filled-honeypot submissions.\n  const payload = {}\n  for (const [name, value] of new FormData(form).entries()) {\n    payload[name] = typeof value === 'string' ? value : value.name\n  }\n\n  const action = form.getAttribute('action') || ''\n\n  let response\n  try {\n    response = await fetch(action, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(payload),\n    })\n  } catch (_e) {\n    showError(form, 'Could not reach the server. Please try again.')\n    return\n  }\n\n  if (response.ok) {\n    const root = form.closest(ROOT_SELECTOR)\n    const success = root ? root.querySelector(SUCCESS_SELECTOR) : null\n    const successHtml =\n      success && 'content' in success ? success.innerHTML : success ? success.innerHTML : ''\n    if (root) {\n      root.innerHTML = successHtml || '<p>Thanks — your message has been sent.</p>'\n    }\n    return\n  }\n\n  // Non-2xx: surface the server's error inline without navigating away.\n  let message = `Something went wrong (${response.status}). Please try again.`\n  try {\n    const body = await response.json()\n    if (body && typeof body.error === 'string' && body.error) {\n      message = body.error\n    }\n  } catch (_e) {\n    // Non-JSON error body — keep the status-based default message.\n  }\n  showError(form, message)\n}\n\n/** Attach the JSON-submit enhancement to a single contact form. */\nexport function enhanceContactForm(form) {\n  form.addEventListener('submit', function (event) {\n    void handleSubmit(form, event)\n  })\n}\n\n/** Enhance every contact form in `root` (defaults to `document`). */\nexport function enhanceAllContactForms(root) {\n  const scope = root || (typeof document !== 'undefined' ? document : null)\n  if (!scope) return\n  const forms = scope.querySelectorAll('form[data-contact-form]')\n  for (let i = 0; i < forms.length; i++) enhanceContactForm(forms[i])\n}\n\n// Auto-init when shipped to the browser; inert under Node/JSDOM-less imports.\nif (typeof document !== 'undefined') {\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', function () {\n      enhanceAllContactForms()\n    })\n  } else {\n    enhanceAllContactForms()\n  }\n}\n\n/* behavior: carousel */\n/**\n * Vetted client behaviour for the `carousel` behavior (REQ-85).\n *\n * A behavior module ships fixed, tested behavioural CODE — this is the\n * carousel's. It is authored as self-contained browser JavaScript (no imports)\n * so the render pipeline can ship it verbatim as a static `capabilities.js`\n * asset; the pure algorithm is unit-tested by importing this module directly.\n *\n * Behaviour: the SSR baseline is a pure CSS `scroll-snap` track (usable with no\n * JS). This upgrades it — `data-carousel-autoplay` advances the track on a timer,\n * `data-carousel-loop` wraps from the last slide back to the first.\n *\n * **Isolation** (REQ-85): every entry point is defensive — a missing element, a\n * one-slide track, or an absent timer API degrades to the static baseline and\n * never throws, so a misbehaving carousel can never break page robustness.\n */\n\nconst AUTOPLAY_INTERVAL_MS = 5000\n\n/** Advance a track by one slide, wrapping to the start when `loop` and at the end. */\nexport function advanceTrack(track, loop) {\n  const slide = track.querySelector('.carousel__slide')\n  const step = slide ? slide.getBoundingClientRect().width : track.clientWidth\n  const atEnd = track.scrollLeft + track.clientWidth >= track.scrollWidth - 1\n  if (atEnd) {\n    if (loop) track.scrollTo({ left: 0, behavior: 'smooth' })\n    return\n  }\n  track.scrollBy({ left: step, behavior: 'smooth' })\n}\n\n/**\n * REQ-96 — mark the dot matching the slide nearest the track's scroll position.\n *\n * Which slide is current is a *behavioural state*, so the module owns it: a dot's\n * look is an L1 subtree, and a static subtree has no state axis to say \"this one\"\n * with. The module marks it and gives it the one invariant opacity rule; L1 keeps\n * everything else.\n */\nexport function syncDots(section, track) {\n  const dots = section.querySelectorAll('[data-carousel-dot]')\n  if (dots.length === 0) return\n  const slides = track.querySelectorAll('.carousel__slide')\n  let current = 0\n  let best = Infinity\n  for (let i = 0; i < slides.length; i++) {\n    const distance = Math.abs(slides[i].offsetLeft - track.scrollLeft)\n    if (distance < best) {\n      best = distance\n      current = i\n    }\n  }\n  for (let i = 0; i < dots.length; i++) {\n    if (i === current) dots[i].setAttribute('data-carousel-current', '')\n    else dots[i].removeAttribute('data-carousel-current')\n  }\n}\n\n/**\n * Attach the dot indicator and autoplay/loop to one carousel `<section>`.\n * `schedule` is injectable so the behaviour is unit-testable without a real\n * timer; it defaults to the global `setInterval`.\n */\nexport function enhanceCarousel(section, schedule) {\n  try {\n    // The indicator is independent of autoplay, and its own failure must not cost\n    // the track its autoplay — hence its own guard rather than the outer one.\n    try {\n      const dotTrack = section.querySelector('.carousel__track')\n      if (dotTrack && typeof dotTrack.addEventListener === 'function') {\n        dotTrack.addEventListener('scroll', function () {\n          try {\n            syncDots(section, dotTrack)\n          } catch (_e) {\n            // A failed indicator update must never break scrolling.\n          }\n        })\n      }\n    } catch (_e) {\n      // No indicator; the track still scrolls and still autoplays.\n    }\n    if (!section.hasAttribute('data-carousel-autoplay')) return\n    const loop = section.hasAttribute('data-carousel-loop')\n    const track = section.querySelector('.carousel__track')\n    if (!track || track.querySelectorAll('.carousel__slide').length < 2) return\n    const timer = schedule || (typeof setInterval === 'function' ? setInterval : null)\n    if (!timer) return\n    timer(function () {\n      try {\n        advanceTrack(track, loop)\n      } catch (_e) {\n        // A single failed advance must never break the page.\n      }\n    }, AUTOPLAY_INTERVAL_MS)\n  } catch (_e) {\n    // Isolation: enhancement failure degrades to the no-JS baseline.\n  }\n}\n\n/** Enhance every carousel in `root` (defaults to `document`). */\nexport function enhanceAllCarousels(root) {\n  const scope = root || (typeof document !== 'undefined' ? document : null)\n  if (!scope) return\n  const sections = scope.querySelectorAll('[data-carousel]')\n  for (let i = 0; i < sections.length; i++) enhanceCarousel(sections[i])\n}\n\n// Auto-init when shipped to the browser; inert under Node/JSDOM-less test imports.\nif (typeof document !== 'undefined') {\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', function () {\n      enhanceAllCarousels()\n    })\n  } else {\n    enhanceAllCarousels()\n  }\n}"
